        # Step 2: Enter authorized username (resolved at run time from origin-scoped credentials)
        page.locator('#login-email').first.fill(credential("username"))
        # Step 3: Enter authorized password (resolved at run time from origin-scoped credentials)
        page.locator('#login-password').first.fill(credential("password"))
